-- ReadyScore V19.2 — Learning Preference data/runtime activation
-- Depends on 20260927150000_v19_2_learning_preference so the new enum values
-- are committed before they are used below.

UPDATE "TestType" SET "status"='ACTIVE', "runtimeKey"='LEARNING_PREFERENCE', "description"='Customer-facing Learning Preference assessment V19.2 covering Visual, Auditory, and Kinesthetic preferences.' WHERE "code"='LEARNING_PREFERENCE';
UPDATE "AssessmentConfigurationVersion" SET "questionPackageVersionId"='learning-preference-runtime-version' WHERE "id"='learning-preference-v1-version';

ON CONFLICT ("productId","type","resourceType","resourceKey") DO UPDATE SET "metadata"=EXCLUDED."metadata";

WITH active_bundle AS (
  SELECT DISTINCT ON (ue."userId") ue."userId", ue."productId", ue."sourceOrderId", ue."startsAt", ue."endsAt" FROM "UserEntitlement" ue WHERE ue."productId" IN ('product-medium','product-advance') AND ue."status"='ACTIVE' AND ue."startsAt" <= CURRENT_TIMESTAMP AND (ue."endsAt" IS NULL OR ue."endsAt" > CURRENT_TIMESTAMP) ORDER BY ue."userId", CASE WHEN ue."productId"='product-advance' THEN 2 ELSE 1 END DESC, ue."updatedAt" DESC
)
SELECT concat('v19lp_',substr(md5(ab."userId" || ':' || x."type" || ':' || x."resourceKey"),1,24)), ab."userId",ab."productId",x."type",'TEST_TYPE',x."resourceKey",'ACTIVE','V19.2_LEARNING_PREFERENCE_BACKFILL',ab."sourceOrderId",1,0,ab."startsAt",ab."endsAt" FROM active_bundle ab CROSS JOIN (VALUES ('TEST_ACCESS'::"EntitlementType",'LEARNING_PREFERENCE'),('RESULT_ACCESS'::"EntitlementType",'LEARNING_PREFERENCE')) x("type","resourceKey") WHERE NOT EXISTS (SELECT 1 FROM "UserEntitlement" existing WHERE existing."userId"=ab."userId" AND existing."type"=x."type" AND existing."resourceType"='TEST_TYPE' AND existing."resourceKey"=x."resourceKey") ON CONFLICT ("userId","type","resourceType","resourceKey") DO NOTHING;
UPDATE "Product" SET "description"='IQ + EQ + DISC + RIASEC + Work Attitude + Learning Preference with the initial assessment entitlement for each.' WHERE "id"='product-medium';
UPDATE "Product" SET "description"='All available assessment types including Work Attitude and Learning Preference, plus Cross-Test Profiling and the personalized V15 report.' WHERE "id"='product-advance';
